 public static function table(Table $table):Table{return $table->columns([TextColumn::make('title')->label('Titre')->searchable()->sortable()->description(fn(Page $p)=>$p->slug),TextColumn::make('status')->badge()->color(fn($state)=>$state==='published'?'success':'gray')->sortable(),TextColumn::make('published_at')->label('Publication')->dateTime('d/m/Y H:i')->placeholder('—')->sortable(),TextColumn::make('legacy_modified_at')->label('Modifié (legacy)')->dateTime('d/m/Y H:i')->placeholder('—')->sortable()->toggleable()])->filters([SelectFilter::make('status')->options(['draft'=>'Brouillon','published'=>'Publié'])])->recordActions([static::viewOnSiteAction()->visible(fn(Page $p):bool=>!$p->trashed()),EditAction::make()->visible(fn(Page $p):bool=>!$p->trashed()),static::trashAction(),static::restoreAction(),static::forceDeleteAction()])->toolbarActions([\Filament\Actions\BulkActionGroup::make([\Filament\Actions\BulkAction::make('trash_404')->label('Corbeille (404)')->requiresConfirmation()->action(fn($records)=>$records->each(fn(Page $p)=>static::trash($p,['status_code'=>404]))),\Filament\Actions\BulkAction::make('trash_410')->label('Corbeille (410)')->requiresConfirmation()->action(fn($records)=>$records->each(fn(Page $p)=>static::trash($p,['status_code'=>410]))),\Filament\Actions\BulkAction::make('restore')->label('Restaurer')->action(fn($records)=>$records->each(fn(Page $p)=>static::restore($p))),\Filament\Actions\BulkAction::make('force_delete')->label('Supprimer définitivement')->requiresConfirmation()->action(fn($records)=>$records->each(fn(Page $p)=>static::forceDelete($p)))])])->defaultSort('updated_at','desc')->emptyStateHeading('Aucune page');}
 public static function getPages():array{return ['index'=>Pages\ListPages::route('/'),'create'=>Pages\CreatePage::route('/create'),'edit'=>Pages\EditPage::route('/{record}/edit')];}
}
